const icons={camera:['Id','Pd'],microphone:['xut','yut'],geolocation:['Rd','Om'],notifications:['gmt','mmt'],'clipboard-read':['ept','Vd']};
const labels={camera:'使用你的摄像头',microphone:'使用你的麦克风',geolocation:'获取你的位置信息',notifications:'显示通知','clipboard-read':'查看已复制到剪贴板的文本和图像','pointer-lock':'锁定并使用鼠标',fullscreen:'进入全屏'};
const stop=event=>event.stopPropagation();
function PermissionIcon({name,large=false}){
  const key=icons[name]?.[large?1:0]??(large?'Dct':'kct'),asset=permissionAssets[key];
  return <svg width={asset.width} height={asset.height} viewBox={asset.viewBox} aria-hidden="true" focusable="false" style={{flexShrink:0}} dangerouslySetInnerHTML={{__html:asset.body}}/>;
}
function capabilities(prompt){
  return prompt.permissions.flatMap(permission=>{
    const name=typeof permission==='string'?permission:permission?.name;
    if(name==='media')return prompt.mediaTypes?.map(type=>type==='audio'?'microphone':type==='video'?'camera':null)??[];
    return [name==='pointerLock'?'pointer-lock':name==='geolocation-approximate'?'geolocation':name];
  }).filter(name=>typeof name==='string'&&name.length>0);
}
function currentPrompt(prompt,scope,pageUrl){
  if(!(prompt&&prompt.tabId===scope.tabId&&typeof prompt.promptId==='string'&&prompt.promptId.length>0
    &&(prompt.actorId===undefined||prompt.actorId===scope.actor)
    &&Number.isSafeInteger(prompt.promptGeneration)&&prompt.promptGeneration>0
    &&prompt.rootUrl===pageUrl&&typeof prompt.requestingOrigin==='string'
    &&Array.isArray(prompt.permissions)&&prompt.permissions.length>0
    &&Array.isArray(prompt.availableActions)&&prompt.availableActions.length>0))return false;
  if(prompt.presentation==='electron-permission-callback')return prompt.variant==='main-frame-once'
    &&prompt.frameUrl===pageUrl&&prompt.permissions.every(permission=>typeof permission==='string')
    &&prompt.availableActions.every(action=>['allow-once','block','dismiss'].includes(action))&&capabilities(prompt).length>0;
  const pluginProvider=prompt.provider==='opencu-permission-store'||prompt.source==='opencu-permission-store';
  const deviceSelection=prompt.provider==='opencu-permission-store'&&prompt.variant==='device-selection';
  if(prompt.variant==='device-selection'&&!deviceSelection)return false;
  if(deviceSelection){
    if(!Array.isArray(prompt.devices)||prompt.devices.length<1||prompt.devices.length>256)return false;
    const ids=new Set();
    for(const device of prompt.devices){
      if(!device||typeof device.deviceId!=='string'||!device.deviceId.trim()||device.deviceId.length>8192
        ||/[\u0000-\u001f\u007f]/.test(device.deviceId)||ids.has(device.deviceId)
        ||typeof device.name!=='string'||!device.name.trim()||device.name.length>512
        ||typeof device.persistentGrantAvailable!=='boolean')return false;
      ids.add(device.deviceId);
    }
  }else if(prompt.devices!==undefined)return false;
  if(!['normal','quiet'].includes(prompt.presentation)
    ||!['ask','administrator-granted','administrator-denied','os-system-settings','os-prompt','previously-denied','previously-granted',
      ...(prompt.provider==='opencu-permission-store'?['website-permission','device-selection']:[])].includes(prompt.variant)
    ||!prompt.permissions.every(permission=>permission&&typeof permission==='object'&&typeof permission.name==='string')
    ||!prompt.availableActions.every(action=>['allow','allow-this-time','deny','dismiss'].includes(action))
    ||(!pluginProvider||prompt.requestingFrame!==undefined)&&(!Number.isSafeInteger(prompt.requestingFrame?.processId)||!Number.isSafeInteger(prompt.requestingFrame?.routingId)))return false;
  try{
    const frame=new URL(prompt.frameUrl),root=new URL(pageUrl);
    if(!['http:','https:'].includes(frame.protocol)||frame.origin!==prompt.requestingOrigin||root.origin!==prompt.embeddingOrigin)return false;
  }catch{return false;}
  if(prompt.geolocation!==undefined&&(!Array.isArray(prompt.geolocation?.availableAccuracies)
    ||!prompt.geolocation.availableAccuracies.length
    ||!prompt.geolocation.availableAccuracies.every(value=>['approximate','precise'].includes(value))
    ||!prompt.geolocation.availableAccuracies.includes(prompt.geolocation.initialAccuracy)))return false;
  return capabilities(prompt).length>0;
}
function PermissionPrompt({prompt,respond}){
  const anchor=useRef(null),readyAfter=useRef(Infinity),pending=useRef(false);
  const[open,setOpen]=useState(prompt.presentation!=='quiet'),[action,setAction]=useState(null),[failed,setFailed]=useState(false);
  const pluginProvider=prompt.provider==='opencu-permission-store',deviceSelection=pluginProvider&&prompt.variant==='device-selection';
  const[accuracy,setAccuracy]=useState(pluginProvider?undefined:prompt.geolocation?.initialAccuracy);
  const[deviceId,setDeviceId]=useState(()=>deviceSelection&&prompt.devices.length===1?prompt.devices[0].deviceId:'');
  const selectedDevice=deviceSelection?prompt.devices.find(device=>device.deviceId===deviceId):undefined;
  const titleId=useId(),descriptionId=useId(),permissions=capabilities(prompt);
  const label='来自 '+prompt.requestingOrigin+' 的网站权限请求';
  const grants=name=>['allow','allow-this-time','allow-once'].includes(name);
  const permitted=name=>prompt.availableActions.includes(name)&&(!deviceSelection||!grants(name)
    ||!!selectedDevice&&(name!=='allow'||selectedDevice.persistentGrantAvailable));
  const run=async(name,event)=>{
    const system=name==='open-system-settings'&&prompt.variant==='os-system-settings';
    if(pending.current||!system&&!permitted(name))return;
    if(event&&event.isTrusted!==true&&event.nativeEvent?.isTrusted!==true)return;
    if(name!=='dismiss'){
      const now=performance.now(),blocked=now<readyAfter.current;readyAfter.current=now+500;
      if(blocked||!document.hasFocus())return;
    }
    pending.current=true;setAction(name);setFailed(false);
    try{
      const response={action:name,...(!pluginProvider&&['allow','allow-this-time'].includes(name)&&accuracy?{geolocationAccuracy:accuracy}:{}),
        ...(deviceSelection&&grants(name)?{deviceId:selectedDevice.deviceId}:{})};
      const result=await respond(prompt,response,system);
      if(result.closed)setOpen(false);
    }
    catch{setFailed(true);}
    finally{pending.current=false;setAction(null);}
  };
  const dismiss=event=>void run('dismiss',event);
  const trigger=<CodexCuTooltip tooltipContent={label} disabled={open}><CodexCuButton type="button" unstyled focusRing="inset" className="codex-cu-site-information-button" aria-label={label} aria-expanded={open} aria-haspopup="dialog" data-browser-sidebar-skip-address-commit="true" onPointerDown={stop} onMouseDown={stop} onClick={event=>{stop(event);if(open)dismiss(event);else setOpen(true);}}><PermissionIcon name={permissions.length===1?permissions[0]:null}/></CodexCuButton></CodexCuTooltip>;
  const content=<CodexCuPopoverSurface opaque aria-labelledby={titleId} aria-describedby={descriptionId} className="cuc-select-none cuc-no-drag" onClick={stop} onKeyDown={event=>{if(event.repeat&&['Enter',' '].includes(event.key))event.preventDefault();}}>
    <div className="cuc-flex cuc-flex-col cuc-gap-3 cuc-p-3">
      <div className="cuc-flex cuc-items-start cuc-justify-between cuc-gap-2">
        <div id={titleId} data-slot="popover-title" className="cuc-font-medium"><bdi className="cuc-break-all cuc-select-text">{prompt.requestingOrigin.replace(/^https:\/\//,'')}</bdi> 想要</div>
        {prompt.availableActions.includes('dismiss')&&<CodexCuButton color="ghostSecondary" size="compact" uniform aria-label="关闭权限请求" disabled={action!=null} onClick={dismiss}><CodexCuIcon name="shared:Cot"/></CodexCuButton>}
      </div>
      {prompt.embeddingOrigin&&prompt.embeddingOrigin!==prompt.requestingOrigin&&<div>嵌入在 <bdi className="cuc-break-all cuc-select-text">{prompt.embeddingOrigin.replace(/^https:\/\//,'')}</bdi> 中</div>}
      <div id={descriptionId}><ul className="cuc-flex cuc-flex-col cuc-gap-1 cuc-text-sm">{permissions.map((permission,index)=><li key={permission+index} className="cuc-flex cuc-items-start cuc-gap-2"><PermissionIcon name={permission} large/><div>{labels[permission]??<>使用 <bdi>{permission}</bdi></>}</div></li>)}</ul></div>
      {deviceSelection&&<label className="cuc-flex cuc-min-w-0 cuc-flex-col cuc-gap-1 cuc-text-sm">
        <span>设备</span>
        <select aria-label="选择设备" value={selectedDevice?.deviceId??''} disabled={action!=null} style={{width:'100%',minWidth:0,maxWidth:'100%'}}
          onChange={event=>{if(action==null)setDeviceId(prompt.devices.find(device=>device.deviceId===event.currentTarget.value)?.deviceId??'');}}>
          <option value="" disabled>选择设备</option>
          {prompt.devices.map(device=><option key={device.deviceId} value={device.deviceId}>{device.name}</option>)}
        </select>
      </label>}
      {!pluginProvider&&prompt.geolocation?.availableAccuracies.length>1&&<fieldset className="cuc-flex cuc-flex-col cuc-gap-1 cuc-text-sm" disabled={action!=null}><legend>位置精度</legend>{prompt.geolocation.availableAccuracies.map(value=><label key={value} className="cuc-flex cuc-items-center cuc-gap-2"><input type="radio" name={titleId+'-accuracy'} value={value} checked={accuracy===value} onChange={()=>setAccuracy(value)}/>{value==='precise'?'精确位置':'大致位置'}</label>)}</fieldset>}
      {prompt.variant==='os-system-settings'&&<p className="cuc-text-sm">此权限已被系统关闭。</p>}
      {prompt.variant==='administrator-denied'&&<p className="cuc-text-sm">此权限已被管理策略禁止。</p>}
      {prompt.variant==='administrator-granted'&&<p className="cuc-text-sm">此权限已由管理策略授予。</p>}
      {failed&&<p role="alert" className="cuc-text-sm cuc-text-danger">未能发送你的选择，请重试。</p>}
      <div className="cuc-flex cuc-flex-col cuc-gap-2">{['allow-this-time','allow-once','allow','deny','block'].filter(name=>prompt.availableActions.includes(name)
        &&(!deviceSelection||name!=='allow'||selectedDevice?.persistentGrantAvailable===true)).map(name=><CodexCuButton key={name} color="secondary" size="dialog" disabled={action!=null||!permitted(name)} loading={action===name} onClick={event=>void run(name,event)}>{['allow-this-time','allow-once'].includes(name)?'本次允许':name==='allow'?deviceSelection?'始终允许此设备':'允许':'不允许'}</CodexCuButton>)}{prompt.variant==='os-system-settings'&&<CodexCuButton color="secondary" size="dialog" disabled={action!=null} loading={action==='open-system-settings'} onClick={event=>void run('open-system-settings',event)}>打开系统设置</CodexCuButton>}</div>
    </div>
  </CodexCuPopoverSurface>;
  return <span ref={anchor} onClick={stop} data-browser-permission-prompt={prompt.promptId}>
    {trigger}
    <CodexCuOverlay type="popover" open={open} anchorRef={anchor} manageTrigger={false} align="start" sideOffset={4} collisionPadding={6} content={content} onOpenChange={(value,details)=>{if(value)setOpen(true);else dismiss(details?.originalEvent);}} onOpenAutoFocus={event=>{event.preventDefault();readyAfter.current=performance.now()+500;}} onCloseAutoFocus={event=>event.preventDefault()} onInteractOutside={event=>event.preventDefault()}/>
  </span>;
}

export function BrowserPermissions({sessionId,scope,api,pageUrl,documentKey,visible,onError,children}){
  const[prompt,setPrompt]=useState(null),alive=useRef(false),lifetime=useRef(null),request=useRef(null),responding=useRef(false),revision=useRef(0);
  const callbacks=useRef(null);callbacks.current={onError};
  const backend=useMemo(()=>createCodexBrowserBackend(api,sessionId,scope),[api,sessionId,scope?.browserId,scope?.tabId,scope?.actor,scope?.controlEpoch]);
  const refresh=useCallback(async signal=>{
    if(responding.current)return;const readRevision=revision.current;
    const status=await backend.call('profileStatus',{},signal);
    if(status.sitePermissions?.available!==true){if(alive.current&&!signal.aborted)setPrompt(null);return;}
    const result=await backend.call('permissions.list',{},signal);
    if(!Array.isArray(result))throw new Error('浏览器返回了无效的权限请求');
    if(alive.current&&!signal.aborted&&!responding.current&&readRevision===revision.current)setPrompt(result.find(value=>currentPrompt(value,scope,pageUrl))??null);
  },[backend,pageUrl]);
  useEffect(()=>{
    alive.current=true;setPrompt(null);const controller=new AbortController();lifetime.current=controller;
    if(!visible||!scope?.actor||!scope?.tabId)return()=>{alive.current=false;controller.abort();};
    let timer;const poll=async()=>{
      const read=new AbortController();request.current=read;
      try{await refresh(AbortSignal.any([controller.signal,read.signal]));}
      catch(error){if(alive.current&&!controller.signal.aborted&&!read.signal.aborted){setPrompt(null);if(!['BROWSER_PROFILE_UNAVAILABLE','STALE_BROWSER_PROFILE','VIEW_CHANGED','EXTENSION_CONNECTION_CHANGED'].includes(error.code))callbacks.current.onError?.(error.message);}}
      if(alive.current&&!controller.signal.aborted)timer=setTimeout(poll,500);
    };
    void poll();return()=>{alive.current=false;controller.abort();request.current?.abort();clearTimeout(timer);};
  },[refresh,documentKey,visible]);
  const respond=async(value,response,system=false)=>{
    const signal=lifetime.current.signal;
    responding.current=true;revision.current++;request.current?.abort();
    try{
      const result=await backend.call(system?'permissions.openSystemSettings':'permissions.respond',{promptId:value.promptId,promptGeneration:value.promptGeneration,...(value.leaseId===undefined?{}:{leaseId:value.leaseId}),...(system?{}:{response}),explicitUserCommand:true},signal);
      if(result?.accepted!==true||!system&&result.closed!==true||result.promptId!==value.promptId||result.promptGeneration!==value.promptGeneration)throw new Error('浏览器未确认权限选择');
      if(result.closed&&alive.current&&!signal.aborted)setPrompt(current=>current?.promptId===value.promptId&&current.promptGeneration===value.promptGeneration?null:current);
      return result;
    }finally{revision.current++;responding.current=false;}
  };
  return prompt?<PermissionPrompt key={prompt.promptId+':'+prompt.promptGeneration} prompt={prompt} respond={respond}/>:children;
}
